export function lookupICD10Code(code: string): ICD10ClinicalEntry | undefined {
  return MASTER_ICD10_CLINICAL_REGISTRY.find(e => e.code === code);
}
export function searchICD10ByKeyword(query: string): ICD10ClinicalEntry[] {
  const q = query.toLowerCase();
  return MASTER_ICD10_CLINICAL_REGISTRY.filter(e => e.code.toLowerCase().includes(q) || e.title.toLowerCase().includes(q));
}
